/bin/bash -lc "cat <<'EOF' > lib/posts.ts
import { unstable_cache } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  createdAt: string;
};

type PostsStore = {
  posts: Post[];
};

const globalForPosts = globalThis as typeof globalThis & {
  __postsStore?: PostsStore;
};

const postsStore: PostsStore =
  globalForPosts.__postsStore ?? {
    posts: []
  };

if ("'!globalForPosts.__postsStore) {
  globalForPosts.__postsStore = postsStore;
}

export async function addPost(title: string) {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    createdAt: new Date().toISOString()
  };

  postsStore.posts.unshift(post);

  return post;
}

export const getPosts = unstable_cache(
  async () => {
    return postsStore.posts.slice();
  },
  ['"'posts'],
  {
    tags: ['posts']
  }
);
EOF"

